# Patch: allow add-to-cart without price. Run from the project folder (where package.json is).
$ErrorActionPreference = "Stop"
if (-not (Test-Path "package.json")) { throw "Run this inside the project folder." }
function W($path, $b64) {
  $full = Join-Path (Get-Location) $path
  $dir = Split-Path $full -Parent
  if (-not (Test-Path -LiteralPath $dir)) { New-Item -ItemType Directory -Path $dir -Force | Out-Null }
  [System.IO.File]::WriteAllBytes($full, [Convert]::FromBase64String($b64))
  Write-Host "wrote $path"
}
W 'messages/ar.json' ''
W 'messages/en.json' ''
W 'messages/fr.json' ''
W 'src/app/[locale]/catalogue/[slug]/page.tsx' ''
W 'src/components/CartView.tsx' ''
W 'src/components/ProductBuy.tsx' ''
W 'src/components/ProductCard.tsx' ''
W 'src/components/admin/OrdersList.tsx' ''
W 'src/lib/types.ts' ''
Write-Host "Done."
